import{_ as p,o,c as s,ag as t}from"./chunks/framework.KxDd3USm.js";const _=JSON.parse('{"title":"09.8 课后考题","description":"","frontmatter":{},"headers":[],"relativePath":"09-计算机系统基础/90-课后考题.md","filePath":"09-计算机系统基础/90-课后考题.md"}'),n={name:"09-计算机系统基础/90-课后考题.md"};function e(a,r,b,g,c,C){return o(),s("div",null,[...r[0]||(r[0]=[t('<h1 id="_09-8-课后考题" tabindex="-1">09.8 课后考题 <a class="header-anchor" href="#_09-8-课后考题" aria-label="Permalink to &quot;09.8 课后考题&quot;">​</a></h1><blockquote><p>建议先独立完成，再翻到文件末尾核对答案。</p></blockquote><h3 id="一、选择题-15-题" tabindex="-1">一、选择题（15 题） <a class="header-anchor" href="#一、选择题-15-题" aria-label="Permalink to &quot;一、选择题（15 题）&quot;">​</a></h3><p><strong>1.</strong> 8 位补码 <code>1110 1100</code> 表示的十进制数是（ ）。</p><p>A. −20<br> B. −19<br> C. 236<br> D. −108</p><p><strong>2.</strong> 对长度相同的两种浮点格式，格式甲的阶码比格式乙长、尾数比格式乙短。在其他约定相同的情况下，正确的是（ ）。</p><p>A. 甲的范围更大、精度更低<br> B. 甲的范围更小、精度更高<br> C. 甲的范围和精度都更大<br> D. 阶码只影响精度，尾数只影响范围</p><p><strong>3.</strong> CPU 中保存下一条将要执行的指令地址的是（ ）。</p><p>A. IR<br> B. PC<br> C. MAR<br> D. PSW</p><p><strong>4.</strong> 以下关于存储器的说法，正确的是（ ）。</p><p>A. DRAM 不需刷新，通常用于 Cache<br> B. SRAM 需周期刷新，通常用于主存<br> C. 时间局部性是指刚访问的数据可能很快再次访问<br> D. 磁带属于随机存取存储器</p><p><strong>5.</strong> 地址范围为 <code>2000H～5FFFH</code>，按字节编址，其容量是（ ）。</p><p>A. 8 KiB<br> B. 16 KiB<br> C. 24 KiB<br> D. 32 KiB</p><p><strong>6.</strong> 某系统 Cache 命中率为 90%，题目规定命中访问时间为 5 ns、未命中的完整访问时间为 50 ns，则平均访问时间为（ ）。</p><p>A. 5.0 ns<br> B. 9.5 ns<br> C. 10.0 ns<br> D. 45.5 ns</p><p><strong>7.</strong> 在 Cache 映射方式中，冲突率最低但比较电路最复杂的是（ ）。</p><p>A. 直接映射<br> B. 全相联映射<br> C. 组相联映射<br> D. 顺序映射</p><p><strong>8.</strong> 某磁盘转速为 6000 RPM，不计传输时间，平均寻道时间为 7 ms，则平均存取时间约为（ ）。</p><p>A. 7 ms<br> B. 10 ms<br> C. 12 ms<br> D. 17 ms</p><p><strong>9.</strong> 适合主存与高速外设之间成批传输数据、传输过程主要由专用控制器完成的是（ ）。</p><p>A. 程序查询<br> B. 中断<br> C. DMA<br> D. 轮询</p><p><strong>10.</strong> 中断向量通常提供（ ）。</p><p>A. 被中断程序的数据区地址<br> B. 中断服务程序入口地址<br> C. 外设中待传数据本身<br> D. 下一条普通指令的操作码</p><p><strong>11.</strong> 若 A=120，主存 (120)=600，(600)=45，则采用间接寻址得到的操作数是（ ）。</p><p>A. 45<br> B. 120<br> C. 600<br> D. 720</p><p><strong>12.</strong> 下列特征中，不属于 RISC 的是（ ）。</p><p>A. 指令格式较规整<br> B. 寻址方式较少<br> C. 只有 Load/Store 类指令访问内存<br> D. 大量复杂变长指令并主要采用微程序控制</p><p><strong>13.</strong> 一条指令分为 2 ns、3 ns、4 ns 三段。按理论公式，流水执行 10 条指令所需时间是（ ）。</p><p>A. 36 ns<br> B. 40 ns<br> C. 45 ns<br> D. 90 ns</p><p><strong>14.</strong> 两个相互独立、可靠度均为 0.8 的部件并联，只要一个正常系统就正常，系统可靠度为（ ）。</p><p>A. 0.64<br> B. 0.80<br> C. 0.96<br> D. 1.60</p><p><strong>15.</strong> 4 位数据采用能纠正一位错误的海明码，至少需要的校验位数是（ ）。</p><p>A. 2<br> B. 3<br> C. 4<br> D. 5</p><h3 id="二、综合计算题-2-题" tabindex="-1">二、综合计算题（2 题） <a class="header-anchor" href="#二、综合计算题-2-题" aria-label="Permalink to &quot;二、综合计算题（2 题）&quot;">​</a></h3><p><strong>16. Cache 与磁盘综合题</strong></p><p>某系统先访问 Cache，Cache 查询时间为 8 ns，命中率为 96%；若未命中，再追加 92 ns 访问主存。</p><p>（1）求一次访存的平均时间。<br> （2）某磁盘有 6 个记录面，每面 4000 个磁道，每磁道 200 个扇区，每扇区 512 B，求磁盘格式化容量（以 B 和 MiB 表示）。<br> （3）该磁盘转速 10000 RPM，平均寻道时间 4 ms，读取连续 5 个扇区，忽略控制器额外开销，求平均存取时间。</p><p><strong>17. 可靠性与校验综合题</strong></p><p>系统由模块 A 与一个冗余模块串联。A 的可靠度为 0.95；冗余模块由 B、C 并联，B、C 的可靠度均为 0.9，各部件故障相互独立。</p><p>（1）求整个系统可靠度。<br> （2）若某可修复设备 MTTF=1990 h、MTTR=10 h，求稳态可用性。<br> （3）信息位为 <code>1010</code>，生成多项式对应除数为 <code>1101</code>，求 CRC 校验位和发送码字。</p><hr>',41)])])}const i=p(n,[["render",e]]);export{_ as __pageData,i as default};
